const items = $input.all();
const filtered = items.filter(item => {
  const name = (item.json.name || '').toLowerCase();
  return !['.pdf','.jpg','.jpeg','.png','.gif','.mp4','.xlsx','.csv'].some(ext => name.endsWith(ext));
});
console.log('Truth files to process:', filtered.length);
return filtered;

const items = $input.all();
const allContent = items.map(i => i.json?.data || '').join('\n\n');

const paragraphs = allContent
  .split(/\n\s*\n/)
  .map(p => p.trim())
  .filter(p => p.length > 50);

console.log('✅ All truth paragraphs loaded:', paragraphs.length);

return paragraphs.map((para, idx) => ({
  json: {
    paragraphIndex: idx,
    paragraphText: para,
    isTruth: true
  }
}));

const items = $input.all();
const filtered = items.filter(item => {
  const name = (item.json.name || '').toLowerCase();
  return !['.pdf','.jpg','.jpeg','.png','.gif','.mp4','.xlsx','.csv'].some(ext => name.endsWith(ext));
});

if (filtered.length === 0) {
  console.log('❌ No source files found');
  return [];
}

const firstFile = filtered[0];
console.log('📄 Processing FIRST source file:', firstFile.json.name);
console.log('   Remaining files in folder:', filtered.length - 1);

return [firstFile];

const item = $input.first();
const sourceFileItem = $('Filter Source Docs Only').first().json;
const content = item.json?.data || '';

if (!content || content.length < 10) {
  console.log('Skipping empty source file:', sourceFileItem.name);
  return [];
}

// Split into paragraphs
const paragraphs = content
  .split(/\n\s*\n/)
  .map(p => p.trim())
  .filter(p => p.length > 50);

console.log('Source paragraphs from', sourceFileItem.name, ':', paragraphs.length);

return paragraphs.map((para, idx) => ({
  json: {
    sourceFile: sourceFileItem.name,
    fileId: sourceFileItem.id,
    paragraphIndex: idx,
    paragraphText: para,
    isTruth: false
  }
}));

// Get truth paragraphs from Split Truth to Paragraphs node
const truthParagraphs = $('Split Truth to Paragraphs').all().map(i => i.json.paragraphText);

console.log('Truth set size:', truthParagraphs.length);

// Get ALL paragraphs from current source file
const sourceParagraphs = $input.all();
const sourceFileName = sourceParagraphs[0]?.json?.sourceFile || 'Unknown';

console.log('Processing source file:', sourceFileName);
console.log('Source paragraphs:', sourceParagraphs.length);

// Compare function (90% similarity threshold)
function areSimilar(str1, str2, threshold = 0.9) {
  const words1 = new Set(str1.toLowerCase().split(/\s+/));
  const words2 = new Set(str2.toLowerCase().split(/\s+/));
  const intersection = new Set([...words1].filter(w => words2.has(w)));
  const union = new Set([...words1, ...words2]);
  const similarity = union.size ? intersection.size / union.size : 0;
  return similarity >= threshold;
}

// Filter to only unique paragraphs
const uniqueParagraphs = [];
sourceParagraphs.forEach(item => {
  const sourcePara = item.json.paragraphText;
  const isDuplicate = truthParagraphs.some(truthPara => areSimilar(sourcePara, truthPara, 0.9));

  if (!isDuplicate) {
    uniqueParagraphs.push(item);
  }
});

console.log('Unique paragraphs found:', uniqueParagraphs.length);

if (uniqueParagraphs.length === 0) {
  console.log('⚠️ ALL CONTENT IS DUPLICATE - no unique paragraphs');
}

return uniqueParagraphs;

const uniqueData = $input.first().json.data || [];
const sourceFileName = uniqueData[0]?.sourceFile || 'Unknown';

if (uniqueData.length === 0) {
  // All duplicate - create a note document
  const content = `L.A. Dolce Vita - Analysis Results\n${'='.repeat(50)}\n\nSource File: ${sourceFileName}\nResult: ALL CONTENT IS DUPLICATE\n\nThis source file contains no unique content compared to truth documents in _essentials folder.\nYou can safely delete this source file.\n`;

  console.log('⚠️ Building DUPLICATE notice document');
  return [{ json: { content, fileName: `DUPLICATE_${sourceFileName}`, sourceFileName, isDuplicate: true } }];
}

// Has unique content
console.log('✅ Building document with', uniqueData.length, 'unique paragraphs');

let content = `L.A. Dolce Vita - Unique Content Analysis\n${'='.repeat(50)}\n\n`;
content += `Source File: ${sourceFileName}\n`;
content += `Unique Paragraphs: ${uniqueData.length}\n\n`;
content += ${'='.repeat(50)} + '\n\n';

uniqueData.forEach((item, idx) => {
  content += `[${idx + 1}] ${item.paragraphText}\n\n---\n\n`;
});

return [{ json: { content, fileName: `UNIQUE_${sourceFileName}`, sourceFileName, isDuplicate: false } }];

